import assert from 'node:assert/strict';

export async function runMotionAddTextSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{name:'Exterior',text:'Fuera del grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});
  const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),assets:project.assets.images.length,outside:sec().elements[0]}));
  async function frame(id){await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return id?d?.querySelector('[data-id="'+id+'"].nw-motion-selected'):d?.querySelector('[data-motion-canvas]');},{},id);return (await page.$('.nw-motion-dialog iframe')).contentFrame();}
  async function layers(){return page.$$eval('[data-motion-layer]',ns=>ns.map(n=>({id:n.dataset.motionLayer,name:n.querySelector('strong').textContent})));}
  async function add(){const old=await layers();await page.click('[data-motion-add-text]');const row=(await layers()).find(n=>!old.some(e=>e.id===n.id));assert.ok(row);await frame(row.id);return row;}
  async function choose(id){await page.click('[data-motion-layer="'+id+'"]');return frame(id);}
  async function type(id,text,confirm=true){const f=await frame(id),n=await f.$('[data-id="'+id+'"]');await n.focus();await page.keyboard.press('Enter');assert.equal(await n.evaluate(n=>n.isContentEditable),true);await page.keyboard.type(text);if(confirm)await page.keyboard.press('Enter');}
  async function change(selector,value){await page.$eval(selector,(n,v)=>{n.value=v;n.dispatchEvent(new Event('change',{bubbles:true}));},value);}
  async function pose(id,selector='.nw-motion-dialog iframe',gid){return page.evaluate(({id,selector,gid})=>{const f=document.querySelector(selector),d=f.contentDocument,rt=f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id];rt.set(.5);const n=d.querySelector('[data-id="'+id+'"]'),s=d.defaultView.getComputedStyle(n);return {text:n.textContent,x:n.style.getPropertyValue('--nw-sd-x'),z:n.style.getPropertyValue('--nw-sd-z'),alpha:n.style.getPropertyValue('--nw-sd-opacity'),opacity:s.opacity,color:s.color,base:[n.style.left,n.style.top,n.style.width]};},{id,selector,gid});}
  await page.click('.tb-left [data-motion-open]');await frame();await page.click('[data-motion-library-tab="elements"]');const original=await layers();
  // Remove every existing text: adding does not depend on having one to duplicate.
  for(const row of original.slice(3)){await choose(row.id);await page.click('[data-motion-element-remove]');await page.waitForFunction(id=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelector('[data-motion-canvas]')&&!d.querySelector('[data-id="'+id+'"]');},{},row.id);}
  const first=await add();assert.equal(first.name,'Texto nuevo');const neutral=await pose(first.id);assert.equal(neutral.text,'Tu texto');assert.equal(neutral.color,'rgb(245, 243, 237)');assert.equal(neutral.x,'0.00px');assert.equal(neutral.z,'0.00px');assert.equal(neutral.opacity,'1');assert.deepEqual(await page.$$eval('[data-motion-key] option',ns=>ns.map(n=>parseFloat(n.textContent))),[0,100]);
  await type(first.id,'Texto propio <b>literal</b>',false);await change('[data-motion-background]','#ffffff');
  // Adding also confirms pending inline text and cancels the scheduled iframe rebuild.
  const second=await add();assert.equal(second.name,'Texto nuevo 2');assert.equal((await pose(second.id)).color,'rgb(23, 25, 33)');const f=await frame(second.id);assert.equal(await f.$eval('[data-id="'+first.id+'"]',n=>n.textContent),'Texto propio <b>literal</b>');assert.equal(await f.$('[data-id="'+first.id+'"] b'),null);
  await choose(first.id);await page.select('[data-motion-key]',await page.$eval('[data-motion-key] option',n=>n.value));await change('[data-motion-key-property="z"]','-200');await page.$eval('[data-motion-key-more]',n=>n.open=true);await change('[data-motion-key-property="x"]','-40');await change('[data-motion-key-property="opacity"]','50');const prepared=await pose(first.id);assert.equal(prepared.x,'-20.00px');assert.equal(prepared.z,'-100.00px');assert.equal(prepared.alpha,'0.7500');assert.equal(prepared.opacity,'0.75');assert.deepEqual(prepared.base,neutral.base,'Movement preserves the base geometry');
  await page.click('[data-motion-library-tab="library"]');await page.click('[data-motion-template="soft-orbit"]');await page.waitForFunction(()=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('.hd')?.textContent==='Diseño en movimiento.');await page.click('[data-motion-template="iso-focus"]');await frame(first.id);assert.deepEqual(await pose(first.id),prepared);assert.deepEqual((await layers()).map(n=>n.id),[...original.slice(0,3).map(n=>n.id),first.id,second.id]);assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);assert.equal(await page.evaluate(()=>history.length),0);
  await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return {project:JSON.stringify(project),gid:g.id,members:sec().elements.filter(e=>e.parent===g.id),assets:project.assets.images.length,outside:sec().elements[0],scroll:sec().sdEnabled};});assert.equal(inserted.members.length,5);assert.equal(inserted.assets,before.assets+3);assert.equal(inserted.scroll,false,'Time composition works without Director');assert.deepEqual(inserted.outside,before.outside);const text=inserted.members.find(e=>e.id===first.id);assert.equal(text.text,prepared.text);assert.equal(text.mobile.customSize,18);assert.equal(text.sdKeyframesEnabled,true);assert.deepEqual(text.sdKeyframes.map(k=>k.at),[0,100]);assert.equal(text.sdKeyframes[0].x,-40);assert.equal(text.sdKeyframes[0].z,-200);assert.equal(text.sdKeyframes[0].opacity,50);const ids=inserted.members.flatMap(e=>[e.id,...(e.sdKeyframes||[]).map(k=>k.id)]);assert.equal(new Set(ids).size,ids.length);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');const third=await add();assert.equal(third.name,'Texto nuevo 3');await type(third.id,'Agregado después');await page.click('[data-motion-save]');const saved=await page.evaluate(gid=>({project:JSON.stringify(project),members:sec().elements.filter(e=>e.parent===gid),groups:sec().elements.filter(e=>e.nwMotionInstance).length,assets:project.assets.images.length,outside:sec().elements[0]}),inserted.gid);assert.equal(saved.groups,1);assert.equal(saved.members.length,6);assert.equal(saved.assets,inserted.assets);assert.equal(saved.members.find(e=>e.id===third.id).text,'Agregado después');assert.deepEqual(saved.members.find(e=>e.id===first.id),text);assert.deepEqual(saved.outside,before.outside);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),inserted.gid);await frame();await page.click('[data-motion-library-tab="elements"]');await add();await page.click('[data-motion-close]');assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),inserted.project);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),saved.project);
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='add-text-export';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#add-text-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid],{},inserted.gid);const exported=await pose(first.id,'#add-text-export',inserted.gid);for(const key of ['text','x','z','alpha','opacity','color'])assert.equal(exported[key],prepared[key]);assert.equal(await page.$eval('#add-text-export',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]')?.textContent,third.id),'Agregado después');
  console.log('Agregar texto Motion Lab: sin textos previos, edición directa segura, contraste, nombres/IDs únicos, movimiento propio, borradores, Tiempo sin Director, guardar misma instancia, externos, cancelar, historial y exportación OK');
 }finally{
  await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#add-text-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);
 }
}
